/**
 * Where a spoken line's audio comes from — the hybrid narration plan (docs/NARRATION.md):
 *
 *   1. Human recordings: IVU Reads' 500 clips, then IVU narration recordings
 *      (public/narration/human.json, committed with their audio).
 *   2. Rendered voice: lines pre-rendered once by a speech engine into audio files
 *      (public/narration/rendered.json, generated by scripts/render-narration.ts, not committed).
 *   3. Nothing here → the caller falls back to the device's own voice.
 *
 * A passage plays from one catalogue only (whole passage, or every sentence) — voices are never
 * mixed inside one passage. Human always wins over rendered, so recording a line replaces its
 * rendered stand-in with no other change.
 */
import { clipsForPassage as ivuReadsClips, loadClips, sentences } from './ivuReads.ts';

export type CatalogSource = 'recorded' | 'rendered';
export interface NarrationCatalogFile {
  source: 'human' | 'rendered';
  /** Who or what produced the audio, e.g. "IVU narrator" or "say:Tara@165". */
  voice: string;
  /** Speakable text (emoji stripped, whitespace collapsed) → file path relative to ./narration/. */
  clips: Record<string, string>;
  /** Rendered catalogue only: files needed per stage, for "save the voice for offline". */
  stageFiles?: Record<string, string[]>;
}

const EMPTY = (source: 'human' | 'rendered'): NarrationCatalogFile => ({ source, voice: '', clips: {} });
let human: NarrationCatalogFile = EMPTY('human');
let rendered: NarrationCatalogFile = EMPTY('rendered');
let loading: Promise<void> | null = null;

const fetchCatalog = (name: 'human' | 'rendered') =>
  fetch(`./narration/${name}.json`)
    .then((r) => (r.ok ? r.json() : EMPTY(name)))
    .then((d: NarrationCatalogFile) => (d && typeof d.clips === 'object' ? d : EMPTY(name)))
    .catch(() => EMPTY(name));

/** Loads every catalogue once. Missing catalogues just mean "no audio of that kind". */
export function loadNarration(): Promise<void> {
  if (!loading) {
    loading = Promise.all([loadClips(), fetchCatalog('human'), fetchCatalog('rendered')])
      .then(([, h, r]) => { human = h; rendered = r; });
  }
  return loading;
}

/** Installs catalogues directly (tests and build scripts). */
export function setNarrationCatalogs(h: NarrationCatalogFile | null, r: NarrationCatalogFile | null): void {
  human = h ?? EMPTY('human');
  rendered = r ?? EMPTY('rendered');
  loading = Promise.resolve();
}

export function renderedCatalog(): NarrationCatalogFile { return rendered; }

const norm = (s: string) => s.replace(/\s+/g, ' ').trim();

function fromCatalog(cat: NarrationCatalogFile, text: string): string[] | null {
  const t = norm(text);
  const whole = cat.clips[t] ?? cat.clips[t.replace(/[.]$/, '')];
  if (whole) return ['./narration/' + whole];
  const parts = sentences(t);
  if (parts.length < 2) return null;
  const urls = parts.map((p) => cat.clips[p] ?? cat.clips[p.replace(/[.]$/, '')]);
  return urls.every((u): u is string => !!u) ? urls.map((u) => './narration/' + u) : null;
}

/** Audio for a speakable line, best source first; null when only the device voice can say it. */
export function resolveNarration(text: string): { urls: string[]; source: CatalogSource } | null {
  const reads = ivuReadsClips(text);
  if (reads) return { urls: reads, source: 'recorded' };
  const h = fromCatalog(human, text);
  if (h) return { urls: h, source: 'recorded' };
  const r = fromCatalog(rendered, text);
  if (r) return { urls: r, source: 'rendered' };
  return null;
}

// ---------- Offline: save the rendered voice for chosen stages ----------

export const NARRATION_CACHE = 'ivu-narration-v1'; // keep in step with public/sw.js

/** Rendered files needed for these stages (plus Buddy's lines, filed under "all"). */
export function renderedFilesFor(stages: string[]): string[] {
  const sf = rendered.stageFiles ?? {};
  return [...new Set(['all', ...stages].flatMap((s) => sf[s] ?? []))].map((f) => './narration/' + f);
}

/** How many of these stages' rendered files are already stored on this device. */
export async function offlineVoiceStatus(stages: string[]): Promise<{ saved: number; total: number }> {
  await loadNarration();
  const files = renderedFilesFor(stages);
  if (typeof caches === 'undefined' || !files.length) return { saved: 0, total: files.length };
  const cache = await caches.open(NARRATION_CACHE);
  const keys = new Set((await cache.keys()).map((r) => new URL(r.url).pathname));
  const saved = files.filter((f) => keys.has(new URL(f, location.href).pathname)).length;
  return { saved, total: files.length };
}

/** Downloads (from this app's own server) and stores every rendered file for these stages. */
export async function saveVoiceOffline(stages: string[], onProgress?: (done: number, total: number) => void): Promise<{ saved: number; failed: number }> {
  await loadNarration();
  const files = renderedFilesFor(stages);
  if (typeof caches === 'undefined') return { saved: 0, failed: files.length };
  const cache = await caches.open(NARRATION_CACHE);
  let done = 0, failed = 0, i = 0;
  await Promise.all(Array.from({ length: 6 }, async () => {
    while (i < files.length) {
      const f = files[i++];
      try {
        if (!(await cache.match(f))) {
          const res = await fetch(f);
          if (!res.ok) throw new Error(String(res.status));
          await cache.put(f, res);
        }
      } catch { failed++; }
      onProgress?.(++done, files.length);
    }
  }));
  return { saved: done - failed, failed };
}
